/* waitid(2) - Wait for a specific child process termination */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

void safe_exit(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main() {
    pid_t child_pid;
    siginfo_t info;
    const int status_code = 12;

    child_pid = fork();

    if (child_pid == -1) {
        safe_exit("fork failed");
    }

    if (child_pid == 0) {
        // Child process
        printf("Child (PID %d) running and exiting with status %d.\n", getpid(), status_code);
        sleep(1);
        _exit(status_code);
    } else {
        // Parent process
        printf("Parent (PID %d) waiting for child %d using waitid.\n", getpid(), child_pid);

        // Wait specifically for this PID (P_PID) to exit (WEXITED).
        if (waitid(P_PID, child_pid, &info, WEXITED) == -1) {
            safe_exit("waitid failed");
        }

        // Check if the expected child was reaped
        if (info.si_pid == child_pid) {
            printf("waitid successful: Reaped child PID: %d\n", info.si_pid);
            // For WEXITED, si_status holds the exit status
            printf("Child exit status: %d\n", info.si_status);
            if (info.si_status != status_code) {
                fprintf(stderr, "Error: Expected status %d, got %d\n", status_code, info.si_status);
            }
        } else if (info.si_pid == 0) {
             // This path usually only happens if WNOHANG was used and no state change occurred.
             printf("waitid returned 0 but no child changed state.");
        }
    }

    return EXIT_SUCCESS;
}
